/**
 * Activepieces Code piece — Stack 1: Clean, Normalize, Resolve Buyers.
 *
 * Flow position:  Google Sheets (Get Rows)  ->  THIS Code step  ->  enrichment.
 *
 * INPUT  (define one input named `rows` in the Code piece UI, mapped to the
 *         Google Sheets action output — an array of row objects keyed by the
 *         sheet's column headers).
 *
 * OUTPUT { uniqueBuyers: [...], stats: {...} }
 *         One record per real-world buyer company, with every email / contact /
 *         domain / HS code / product seen across that buyer's rows merged in,
 *         and a `needsEnrichment` flag telling the next stack whether we still
 *         have to hunt for an email.
 */

export const code = async (inputs) => {
  // Normalize whatever "Get all rows" hands us into header-keyed row objects.
  // Handles: bare array; {rows|values|body:[...]}; rows nested under `values`;
  // and the column-LETTER shape ({A,B,C...} with row 1 as the header).
  const normSheet = (v) => {
    let rows = Array.isArray(v) ? v
      : (v && (Array.isArray(v.rows) ? v.rows
        : Array.isArray(v.values) ? v.values
        : Array.isArray(v.body) ? v.body : [])) || [];
    if (!Array.isArray(rows)) rows = [];
    rows = rows.map((r) => (r && typeof r.values === 'object' && r.values) ? { row: r.row, ...r.values } : r);
    const lettered = rows.some((r) => r && (r.A !== undefined || r.B !== undefined));
    if (!lettered) return rows;
    const header = rows.find((r) => String(r.row) === '1') || rows[0];
    if (!header) return [];
    const map = {};
    for (const [k, val] of Object.entries(header)) if (k !== 'row') map[k] = String(val).trim();
    const out = [];
    for (const r of rows) {
      if (r === header || String(r.row) === '1') continue;
      const obj = {};
      if (r.row !== undefined) obj.row = r.row;
      for (const [k, val] of Object.entries(r)) {
        if (k === 'row') continue;
        const name = map[k];
        if (name) obj[name] = val;
      }
      out.push(obj);
    }
    return out;
  };
  let rows = normSheet(inputs.rows);

  // ---- helpers -----------------------------------------------------------

  const clean = (v) =>
    (v === null || v === undefined ? '' : String(v))
      .replace(/\s+/g, ' ')
      .trim();

  // Free mailbox providers — a domain from one of these is NOT a company domain.
  const FREE_MAIL = new Set([
    'gmail.com', 'yahoo.com', 'yahoo.co.in', 'hotmail.com', 'outlook.com',
    'live.com', 'aol.com', 'icloud.com', 'rediffmail.com', 'ymail.com',
    'protonmail.com', 'gmx.com', 'mail.com', 'qq.com', '163.com', '126.com',
  ]);

  // Legal suffixes / noise stripped ONLY to build the dedupe key.
  const LEGAL = [
    'private limited', 'pvt ltd', 'pvt. ltd.', 'pvt', 'private', 'limited',
    'ltd', 'llp', 'llc', 'inc', 'incorporated', 'corp', 'corporation',
    'company', 'co', 'gmbh', 'ag', 'bv', 'nv', 'sa', 'srl', 'spa', 'pte',
    'pte ltd', 'sdn bhd', 'sdn', 'bhd', 'plc', 'kg', 'oy', 'as', 'sas',
    'the', 'and', '&',
  ];

  const EMAIL_RE = /[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}/gi;
  const URL_RE = /((https?:\/\/)?(www\.)?)([a-z0-9\-]+\.)+[a-z]{2,}(\/[^\s,;]*)?/gi;

  // Ocean-carrier / customs boilerplate that shows up in Product Description and
  // is pure noise for personalization. Anything from these markers on is dropped.
  const BOILERPLATE_RE =
    /(please note[\s-]+quantity|cargo are based on the shipper|ocean carrier has no knowledge|shipper'?s load and co).*$/is;

  // Pull a human-readable product label out of the messy description:
  //  - prefer the SHIPPER_DESCRIPTION(...) or HSCD_DESCRIPTION(...) parenthetical
  //  - strip trailing carrier boilerplate
  //  - drop stray commas that sit mid-word from the broken CSV export
  const productLabel = (desc) => {
    let s = clean(desc);
    const paren =
      s.match(/SHIPPER_DESCRIPTION\s*\(([^)]+)\)/i) ||
      s.match(/HSCD_DESCRIPTION\s*\(([^)]+)\)/i);
    if (paren) s = paren[1];
    s = s.replace(BOILERPLATE_RE, '');
    // strip trade-data noise: HS/HTS codes, PO numbers, "this shipment"
    s = s.replace(/\b(HS(CD)?|HTS)\s*(CODE)?\s*[:#]?\s*\d[\d.]*/ig, ' ');
    s = s.replace(/\bPO\s*#?\s*[:#]?\s*[A-Z0-9]+/ig, ' ');
    s = s.replace(/\bthis shipment\b/ig, ' ');
    s = s.replace(/,(?=\S)/g, ' ');   // ", " left alone, ",X" -> " X"
    s = s.replace(/\s+/g, ' ').trim().replace(/[,\-]+$/, '').trim();
    return s.slice(0, 120);
  };

  // First 6 digits group HS codes into one product family (482370 == 48237010).
  const hsFamily = (code) => clean(code).replace(/\D/g, '').slice(0, 6);

  const dedupeKey = (name) => {
    let k = clean(name).toLowerCase();
    k = k.replace(/[.,/#!$%^*;:{}=\-_`~()@'"]/g, ' '); // punctuation -> space
    k = k.replace(/\s+/g, ' ').trim();
    // strip legal suffix words (whole words only)
    const parts = k.split(' ').filter((w) => w && !LEGAL.includes(w));
    return parts.join(' ').trim();
  };

  const extractEmails = (text) => {
    const found = clean(text).toLowerCase().match(EMAIL_RE) || [];
    return found.map((e) => e.trim());
  };

  const domainOfEmail = (email) => {
    const m = String(email).toLowerCase().match(/@([a-z0-9.\-]+\.[a-z]{2,})$/);
    return m ? m[1] : '';
  };

  const extractDomain = (contactWeb, emails) => {
    // 1) prefer an explicit website in Contact/Web
    const urls = clean(contactWeb).toLowerCase().match(URL_RE) || [];
    for (const u of urls) {
      const host = u
        .replace(/^https?:\/\//, '')
        .replace(/^www\./, '')
        .split('/')[0]
        .trim();
      if (host && host.includes('.') && !host.includes('@')) return host;
    }
    // 2) otherwise derive from a non-free company email
    for (const e of emails) {
      const d = domainOfEmail(e);
      if (d && !FREE_MAIL.has(d)) return d;
    }
    return '';
  };

  const phoneOf = (text) => {
    const m = clean(text).match(/\+?\d[\d\s\-()]{6,}\d/);
    return m ? m[0].trim() : '';
  };

  const addUniq = (arr, val) => {
    const v = clean(val);
    if (v && !arr.some((x) => x.toLowerCase() === v.toLowerCase())) arr.push(v);
  };

  // Role/department mailboxes that are NOT a person's name.
  const ROLE_LOCALS = new Set(['info', 'sales', 'contact', 'hello', 'admin',
    'office', 'support', 'enquiry', 'enquiries', 'inquiry', 'orders', 'order',
    'purchasing', 'purchase', 'procurement', 'sourcing', 'buyer', 'import',
    'imports', 'export', 'exports', 'accounts', 'finance', 'mail', 'general',
    'marketing', 'team', 'customerservice', 'service', 'help', 'reception']);
  const cap = (s) => s ? s[0].toUpperCase() + s.slice(1).toLowerCase() : '';

  // Derive a person's name from a personal-looking email local-part.
  // "priya.sharma@acme.com" -> {name:'Priya Sharma', first:'Priya'}; role
  // inboxes and gibberish return null so we never greet a fake name.
  const nameFromEmail = (email) => {
    const local = String(email || '').toLowerCase().split('@')[0]
      .replace(/\d+/g, '').replace(/[._-]+/g, '.').replace(/^\.|\.$/g, '');
    if (!local || ROLE_LOCALS.has(local)) return null;
    const parts = local.split('.').filter(Boolean);
    if (parts.length >= 2 && parts.every((p) => p.length >= 2)) {
      return { name: parts.map(cap).join(' '), first: cap(parts[0]) };
    }
    // single token: only trust it as a first name if it's alphabetic & 3-12 chars
    if (parts.length === 1 && /^[a-z]{3,12}$/.test(parts[0]) && !ROLE_LOCALS.has(parts[0])) {
      return { name: cap(parts[0]), first: cap(parts[0]) };
    }
    return null;
  };

  // ---- fold rows into unique buyers -------------------------------------

  const buyers = new Map();
  let skipped = 0;

  for (const raw0 of rows) {
    // some Sheets versions nest the columns under `values`
    const raw = (raw0 && typeof raw0.values === 'object' && raw0.values)
      ? raw0.values : (raw0 || {});
    const buyerName = clean(raw['Buyer']);
    if (!buyerName) { skipped++; continue; }

    const key = dedupeKey(buyerName);
    if (!key) { skipped++; continue; }

    const mailField = clean(raw['Mail ID']);
    const contactField = clean(raw['Contact/Web']);
    const emails = [
      ...extractEmails(mailField),
      ...extractEmails(contactField),
    ].filter((e) => !FREE_MAIL.has(domainOfEmail(e)) || true); // keep all, flag later

    if (!buyers.has(key)) {
      buyers.set(key, {
        buyerKey: key,
        buyerName,               // display name (longest seen wins below)
        domain: '',
        emails: [],
        freeEmails: [],          // gmail/yahoo etc. — usable but low-trust
        phones: [],
        websites: [],
        hsCodes: [],
        hsFamilies: [],
        products: [],
        productLabels: [],
        origins: [],
        destinations: [],
        ports: [],
        sellers: [],
        assignedTo: [],
        shipmentCount: 0,
        lastDate: '',
      });
    }
    const b = buyers.get(key);

    // longest / most complete original name as the display name
    if (buyerName.length > b.buyerName.length) b.buyerName = buyerName;

    for (const e of emails) {
      if (FREE_MAIL.has(domainOfEmail(e))) addUniq(b.freeEmails, e);
      else addUniq(b.emails, e);
    }

    const ph = phoneOf(contactField);
    if (ph) addUniq(b.phones, ph);

    const dom = extractDomain(contactField, emails);
    if (dom && !b.domain) b.domain = dom;
    if (dom) addUniq(b.websites, dom);

    addUniq(b.hsCodes, raw['HS Code']);
    addUniq(b.hsFamilies, hsFamily(raw['HS Code']));
    addUniq(b.products, raw['Product Description']);
    addUniq(b.productLabels, productLabel(raw['Product Description']));
    addUniq(b.origins, raw['Origin']);
    addUniq(b.destinations, raw['Country of Destination'] || raw['Destination']);
    addUniq(b.ports, raw['Port of Origin']);
    addUniq(b.sellers, raw['Seller']);
    addUniq(b.assignedTo, raw['Assigned To']);
    b.shipmentCount += 1;

    const d = clean(raw['Date']);
    if (d && d > b.lastDate) b.lastDate = d;
  }

  // ---- finalize ----------------------------------------------------------

  const uniqueBuyers = [...buyers.values()].map((b) => {
    const hasCompanyEmail = b.emails.length > 0;
    const hasAnyEmail = hasCompanyEmail || b.freeEmails.length > 0;

    // Pull a SPOC name from any personal-looking email the sheet already had.
    let spoc = null;
    let spocEmail = '';
    for (const e of [...b.emails, ...b.freeEmails]) {
      const n = nameFromEmail(e);
      if (n) { spoc = n; spocEmail = e; break; }
    }

    return {
      ...b,
      // prefer a named personal email as the primary contact when we have one
      primaryEmail: spocEmail || b.emails[0] || b.freeEmails[0] || '',
      spocName: spoc ? spoc.name : '',
      spocFirstName: spoc ? spoc.first : '',
      spocEmail,
      // Skip the (rate-limited) email finder when we already have a company email.
      needsEnrichment: !hasCompanyEmail,
      hasAnyEmail,
    };
  });

  // Most active buyers first — spend scarce free finder credits on these.
  uniqueBuyers.sort((a, b) => b.shipmentCount - a.shipmentCount);

  return {
    uniqueBuyers,
    stats: {
      inputRows: rows.length,
      skippedNoBuyer: skipped,
      uniqueBuyers: uniqueBuyers.length,
      alreadyHaveCompanyEmail: uniqueBuyers.filter((b) => !b.needsEnrichment).length,
      needEnrichment: uniqueBuyers.filter((b) => b.needsEnrichment).length,
    },
  };
};

/**
 * Activepieces Code piece — CRM pre-check (dedup + already-found cache).
 *
 * Flow position:  01-clean  ->  THIS  ->  02-enrich.
 *
 * Runs BEFORE domain-finding so we never re-hunt a domain/mail for a company
 * we already know. Three signals, cheapest first:
 *
 *  1. **Already-found log** (the "Found" sheet this engine writes each run):
 *     if this buyer already has a domain/mail on file, reuse it and mark the
 *     buyer done — 02-enrich passes it straight through, no lookup spent.
 *  2. **The CRM** (`GET /lookup`): the source of truth. It answers from SQLite
 *     and includes disqualified/closed companies, so it is a strict superset of
 *     the CRM — asking the CRM already "checks the CRM", and unlike the CRM it won't
 *     re-surface a company we rejected last month. (Service B syncs SQLite ->
 *     the CRM; the CRM lags and drops closed companies, so a direct the CRM read here
 *     would be both redundant and worse — see deploy/ACTIVEPIECES.md.)
 *  3. Unknown -> let it through to enrichment.
 *
 * Classification per buyer:
 *   should_prospect / unknown  -> keep, enrich, pitch
 *   needs_address              -> keep, enrich to find an address, but DON'T
 *                                 pitch (the CRM queues it for follow-up)
 *   known & in-pipeline        -> drop (already being handled)
 *
 * Fail-open: any CRM error leaves the buyer in the pipeline rather than
 * silently dropping a real prospect. The Found-log cache still applies.
 *
 * INPUTS
 *   buyers      = 01.uniqueBuyers
 *   found       = Google Sheets "Get rows" on the Found log tab (may be lettered)
 *   crmBaseUrl  = default https://your-crm.example.com
 *   crmToken    = CRM_API_TOKEN (bearer). Leave blank to run cache-only.
 *
 * OUTPUT { buyers, skipped, stats }
 */

export const code = async (inputs) => {
  const buyers = Array.isArray(inputs.buyers) ? inputs.buyers : [];
  const base = String(inputs.crmBaseUrl || 'https://your-crm.example.com')
    .replace(/\/+$/, '');
  const token = String(inputs.crmToken || '').trim();

  // Normalize Google Sheets "Get all rows" into header-keyed rows — handles the
  // lettered-column shape (A/B/C with row 1 as the header) this account returns.
  const normSheet = (v) => {
    let rows = Array.isArray(v) ? v
      : (v && (Array.isArray(v.rows) ? v.rows
        : Array.isArray(v.values) ? v.values
        : Array.isArray(v.body) ? v.body : [])) || [];
    if (!Array.isArray(rows)) rows = [];
    rows = rows.map((r) => (r && typeof r.values === 'object' && r.values) ? { row: r.row, ...r.values } : r);
    const lettered = rows.some((r) => r && (r.A !== undefined || r.B !== undefined));
    if (!lettered) return rows;
    const header = rows.find((r) => String(r.row) === '1') || rows[0];
    if (!header) return [];
    const map = {};
    for (const [k, val] of Object.entries(header)) if (k !== 'row') map[k] = String(val).trim();
    const out = [];
    for (const r of rows) {
      if (r === header || String(r.row) === '1') continue;
      const obj = {};
      if (r.row !== undefined) obj.row = r.row;
      for (const [k, val] of Object.entries(r)) {
        if (k === 'row') continue;
        const name = map[k];
        if (name) obj[name] = val;
      }
      out.push(obj);
    }
    return out;
  };

  const clean = (s) => (s === null || s === undefined ? '' : String(s)).replace(/\s+/g, ' ').trim();
  const lc = (s) => clean(s).toLowerCase();
  const normDomain = (v) => {
    const h = lc(v).replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
    return h.includes('.') && !h.includes('@') && !h.includes(' ') ? h : '';
  };

  // ---- build the already-found cache from the Found log ------------------
  const found = normSheet(inputs.found);
  const cacheByKey = new Map();
  const cachedDomains = new Set();
  for (const r of found) {
    const key = lc(r.buyerKey || r.buyerName);
    const dom = normDomain(r.domain);
    if (dom) cachedDomains.add(dom);
    if (key && !cacheByKey.has(key)) {
      cacheByKey.set(key, {
        domain: dom,
        spocName: clean(r.spocName),
        spocEmail: clean(r.spocEmail),
        mail: clean(r.mailFound || r.spocEmail),
      });
    }
  }

  const lookup = async ({ domain, name }) => {
    if (!token) return null;
    try {
      const q = domain ? 'domain=' + encodeURIComponent(domain)
        : 'name=' + encodeURIComponent(name);
      const r = await fetch(base + '/lookup?' + q, {
        headers: { Authorization: 'Bearer ' + token },
        signal: AbortSignal.timeout(15000),
      });
      if (!r.ok) return null;
      return await r.json();
    } catch { return null; }
  };
  const sleep = (ms) => new Promise((res) => setTimeout(res, ms));

  // ---- classify each buyer ----------------------------------------------
  const out = [];
  const skipped = [];
  const stats = { input: buyers.length, cacheHits: 0, crmSkipped: 0,
    needsAddress: 0, toEnrich: 0, lookupErrors: 0, kept: 0 };

  for (const b of buyers) {
    const key = lc(b.buyerKey || b.buyerName);
    const sheetDomain = normDomain(b.domain);

    // 1) already-found: reuse cached domain/mail, no lookup, skip enrichment
    const cached = cacheByKey.get(key)
      || (sheetDomain && cachedDomains.has(sheetDomain) ? { domain: sheetDomain } : null);
    if (cached && cached.domain) {
      const mail = b.primaryEmail || cached.mail || '';
      stats.cacheHits++; stats.kept++;
      out.push({ ...b,
        domain: b.domain || cached.domain,
        primaryEmail: mail,
        spocName: b.spocName || cached.spocName || '',
        needsEnrichment: false,
        enrichStatus: mail ? 'role_inbox_ready' : (b.enrichStatus || 'cached'),
        dedupe: 'cache' });
      continue;
    }

    // 2) ask the CRM (covers the CRM). Prefer a domain match; fall back to name.
    const info = await lookup({ domain: sheetDomain, name: b.buyerName });
    await sleep(120);
    if (info === null && token) stats.lookupErrors++;

    if (info && info.known && info.should_prospect === false && !info.needs_address) {
      stats.crmSkipped++;
      skipped.push({ buyerKey: b.buyerKey, buyerName: b.buyerName,
        reason: 'in_pipeline', stage: info.stage });
      continue; // already handled — don't enrich, don't pitch
    }
    if (info && info.needs_address) {
      stats.needsAddress++; stats.kept++;
      out.push({ ...b, needsAddress: true,
        crmCompanyId: info.company_id || null, dedupe: 'crm_needs_address' });
      continue;
    }
    stats.toEnrich++; stats.kept++;
    out.push({ ...b, dedupe: info && info.known ? 'crm_known' : 'new' });
  }

  return { buyers: out, skipped, stats };
};

/**
 * Activepieces Code piece — Stack 2: ICP filter + Domain + Email candidates.
 *
 * Flow position:  Stack-1 Code  ->  THIS Code step  ->  personalization.
 *
 * Zero-cost, no-key, unlimited backbone:
 *   - Clearbit autocomplete  (company name -> domain)   free, no key
 *   - Google DNS-over-HTTPS  (MX check, domain accepts mail?)   free, no key
 *   - Role-inbox permutation (sales@ / purchasing@ ...)   free, unlimited
 *
 * Named decision-maker (SPOC) lookup is intentionally NOT here: there is no
 * free, no-scrape, no-limit source for a person's name at volume. Reserve a
 * paid finder (Apollo/Hunter) for your top buyers and call it from a separate
 * step gated on `icpScore`. This piece gets you a deliverable role inbox for
 * free, which the bounce handler in the send stack de-facto verifies.
 *
 * INPUT  (input `buyers` = Stack-1 uniqueBuyers array; only needsEnrichment
 *         items are processed, the rest pass through untouched)
 *
 * OUTPUT { enriched: [...], stats: {...} }
 */

export const code = async (inputs) => {
  const buyers = Array.isArray(inputs.buyers) ? inputs.buyers : [];

  // ---- ICP config (Acme: compostable sugarcane bagasse tableware) -----
  const ICP_KEYWORDS = [
    'bagasse', 'tableware', 'compostable', 'molded fiber', 'moulded fibre',
    'clamshell', 'plate', 'bowl', 'cup', 'container', 'egg ctn', 'egg carton',
    'paper pulp', 'pressed molded', 'disposable', 'foodservice', 'cutlery',
    'dishware', 'tray',
  ];
  const ICP_HS_FAMILIES = ['482370', '482361', '482369']; // pulp/paper tableware
  const ROLE_PREFIXES = [
    'purchasing', 'procurement', 'purchase', 'sourcing', 'buyer',
    'sales', 'info', 'contact', 'hello', 'import', 'orders',
  ];

  // ---- helpers -----------------------------------------------------------
  const norm = (s) =>
    String(s || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();

  const STOP = new Set(['the', 'and', 'llc', 'inc', 'ltd', 'co', 'corp',
    'corporation', 'company', 'group', 'international', 'enterprises',
    'solution', 'solutions', 'pvt', 'private', 'limited', 'services',
    'trading', 'exports', 'imports',
    // trailing geography common in trade data ("Reynolds ... Canada Inc")
    'usa', 'us', 'uk', 'uae', 'canada', 'mexico', 'singapore', 'malaysia',
    'australia', 'germany', 'france', 'netherlands', 'vietnam', 'thailand',
    'europe', 'asia', 'africa', 'worldwide', 'overseas', 'intl']);

  // significant tokens: drop stopwords and 1-char fragments
  const tokens = (s) =>
    norm(s).split(' ').filter((t) => t.length >= 2 && !STOP.has(t));

  // common generic words that must not stand alone as a high-confidence match
  const COMMON = new Set(['shop', 'store', 'food', 'foods', 'global', 'world',
    'trade', 'star', 'king', 'gold', 'sun', 'eco', 'green', 'pack', 'packaging',
    'india', 'export', 'import', 'universal', 'national', 'general', 'united']);

  // coverage = fraction of the BUYER's significant tokens that appear in the
  // candidate company name. High-confidence requires 1.0 (every buyer word
  // present) so "Bahamas Food Services" does NOT match tourism site "Bahamas".
  const coverage = (buyerName, candidateName) => {
    const A = tokens(buyerName);        // array -> use .length
    const B = new Set(tokens(candidateName)); // set -> use .size
    if (!A.length || !B.size) return 0;
    let hit = 0;
    for (const t of A) if (B.has(t)) hit++;
    return hit / A.length;
  };

  const icpScore = (b) => {
    const text = norm((b.productLabels || []).concat(b.products || []).join(' '));
    const kw = ICP_KEYWORDS.filter((k) => text.includes(norm(k))).length;
    const hsHit = (b.hsFamilies || []).some((h) => ICP_HS_FAMILIES.includes(h));
    // volume signal: repeated shipments = a real distributor, not a one-off
    const vol = Math.min(b.shipmentCount || 1, 5);
    let score = kw * 2 + (hsHit ? 3 : 0) + vol;
    // penalize obvious one-off noise (single shipment, no keyword match)
    if (kw === 0 && (b.shipmentCount || 1) <= 1) score -= 3;
    return score;
  };

  const suggest = async (query) => {
    try {
      const r = await fetch(
        'https://autocomplete.clearbit.com/v1/companies/suggest?query=' +
          encodeURIComponent(query),
        { signal: AbortSignal.timeout(8000) },
      );
      const list = await r.json();
      return Array.isArray(list) ? list : [];
    } catch { return []; }
  };

  const clearbitDomain = async (name) => {
    // Clearbit is a PREFIX match: "Sysco Corporation" -> 0, "Sysco" -> hits.
    // Strip legal noise and try progressively shorter queries until one hits.
    const tk = tokens(name);
    const queries = [...new Set([
      tk.join(' '),
      tk.slice(0, 2).join(' '),
      tk.slice(0, 1).join(' '),
    ].filter(Boolean))];

    let list = [];
    for (const q of queries) {
      list = await suggest(q);
      if (list.length) break;
      await sleep(150);
    }
    if (!list.length) return null;

    // pick the candidate with the highest buyer-token coverage
    let best = null;
    let bestCov = 0;
    for (const c of list) {
      const cov = coverage(name, c.name);
      if (cov > bestCov) { bestCov = cov; best = c; }
    }
    best = best || list[0];

    // 'high' only when the full buyer name is covered — otherwise it's a guess.
    let confidence = bestCov >= 0.999 ? 'high' : 'low';

    // Extra guard: a buyer name that collapses to ONE short/generic token
    // (e.g. "E SHOP ENTERPRISES" -> "shop") matches too many unrelated brands.
    // Require review unless that single token is distinctive (len >= 5, not common).
    const bt = tokens(name);
    if (confidence === 'high' && bt.length === 1) {
      const t = bt[0];
      if (t.length < 5 || COMMON.has(t)) confidence = 'low';
    }
    return { domain: best.domain, confidence, matchedName: best.name, coverage: bestCov };
  };

  const hasMX = async (domain) => {
    try {
      const r = await fetch(
        'https://dns.google/resolve?name=' + domain + '&type=MX',
        { signal: AbortSignal.timeout(8000) },
      );
      const j = await r.json();
      return Array.isArray(j.Answer) && j.Answer.length > 0;
    } catch { return false; }
  };

  const sleep = (ms) => new Promise((res) => setTimeout(res, ms));

  // ---- process -----------------------------------------------------------
  const enriched = [];
  let resolved = 0;
  let noDomain = 0;
  let filteredOut = 0;
  let needsReview = 0;

  for (const b of buyers) {
    const score = icpScore(b);
    const record = { ...b, icpScore: score };

    // buyers we already have an email for: ready to send, no lookup needed
    if (!b.needsEnrichment) {
      enriched.push({ ...record,
        enrichStatus: b.primaryEmail ? 'role_inbox_ready' : 'needs_review' });
      continue;
    }

    // ICP gate: don't spend lookups on off-target one-offs
    if (score < 2) {
      filteredOut++;
      enriched.push({ ...record, enrichStatus: 'skipped_low_icp',
        emailCandidates: [], primaryEmail: '' });
      continue;
    }

    const hit = await clearbitDomain(b.buyerName);
    await sleep(250); // be polite to the free endpoint

    if (!hit || !hit.domain) {
      noDomain++;
      enriched.push({ ...record, enrichStatus: 'no_domain_free',
        domain: '', emailCandidates: [], primaryEmail: '' });
      continue;
    }

    const domain = hit.domain;

    // Low-confidence match = likely the wrong company. Do NOT auto-email it;
    // park it for human/paid review so we never cold-mail a random domain.
    if (hit.confidence !== 'high') {
      needsReview++;
      enriched.push({
        ...record, domain,
        domainConfidence: 'low', matchedName: hit.matchedName,
        emailCandidates: [], primaryEmail: '',
        enrichStatus: 'needs_review',
      });
      continue;
    }

    const mx = await hasMX(domain);
    await sleep(200);

    const candidates = mx ? ROLE_PREFIXES.map((p) => `${p}@${domain}`) : [];
    resolved += candidates.length ? 1 : 0;

    enriched.push({
      ...record,
      domain,
      domainConfidence: hit.confidence,
      matchedName: hit.matchedName,
      hasMX: mx,
      emailCandidates: candidates,
      primaryEmail: candidates[0] || '',      // purchasing@ preferred
      enrichStatus: mx ? 'role_inbox_ready' : 'domain_no_mx',
    });
  }

  return {
    enriched,
    stats: {
      inputBuyers: buyers.length,
      resolvedRoleInbox: resolved,
      needsReview,
      noDomainFree: noDomain,
      filteredLowIcp: filteredOut,
    },
  };
};

/**
 * Activepieces Code piece — Stack 2b: Fallback domain finder CASCADE.
 *
 * Runs on buyers Stack 2 left unresolved (needs_review / no_domain_free) that
 * clear an ICP threshold. Tries search services in order until one yields the
 * company's real website, validated against a directory/marketplace blocklist
 * and the same strict token gate as Stack 2, then MX-checks and builds role
 * inboxes. First hit wins; later services only run if earlier ones came up empty.
 *
 *   1) Brave Search API   (header X-Subscription-Token)
 *   2) Serper.dev         (Google results, header X-API-KEY)
 *   3) Tavily             (AI search, api_key in body)
 *
 * INPUTS:
 *   enriched       = Stack-2 `enriched` array
 *   braveApiKey    | serperApiKey | tavilyApiKey  (any subset; missing = skipped)
 *   maxLookups     = cap on buyers to resolve per run (default 40)
 *   icpThreshold   = min icpScore to bother (default 4)
 *
 * OUTPUT { enriched, stats }
 */

export const code = async (inputs) => {
  const rows = Array.isArray(inputs.enriched) ? inputs.enriched : [];
  const braveKey = inputs.braveApiKey || '';
  const serperKey = inputs.serperApiKey || '';
  const tavilyKey = inputs.tavilyApiKey || '';
  const maxLookups = Number(inputs.maxLookups) > 0 ? Number(inputs.maxLookups) : 40;
  const icpThreshold = Number(inputs.icpThreshold) >= 0 ? Number(inputs.icpThreshold) : 4;

  const ROLE_PREFIXES = ['purchasing', 'procurement', 'purchase', 'sourcing',
    'buyer', 'sales', 'info', 'contact', 'hello', 'import', 'orders'];

  const BLOCKLIST = ['importyeti', 'panjiva', 'zauba', 'volza', 'seair',
    'exportgenius', 'importgenius', 'tradeindia', 'indiamart', 'alibaba',
    'made-in-china', 'linkedin', 'facebook', 'instagram', 'twitter', 'x.com',
    'youtube', 'crunchbase', 'bloomberg', 'dnb.com', 'zoominfo', 'wikipedia',
    'google.', 'amazon.', 'yelp', 'glassdoor', 'justdial', 'yellowpages',
    'opencorporates', 'trademap', 'kompass', 'europages'];

  const norm = (s) => String(s || '').toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
  const STOP = new Set(['the', 'and', 'llc', 'inc', 'ltd', 'co', 'corp',
    'corporation', 'company', 'group', 'international', 'enterprises', 'solution',
    'solutions', 'pvt', 'private', 'limited', 'services', 'trading', 'exports', 'imports']);
  const COMMON = new Set(['shop', 'store', 'food', 'foods', 'global', 'world',
    'trade', 'star', 'king', 'gold', 'sun', 'eco', 'green', 'pack', 'packaging',
    'india', 'export', 'import', 'universal', 'national', 'general', 'united']);
  const tokens = (s) => norm(s).split(' ').filter((t) => t.length >= 2 && !STOP.has(t));
  const coverage = (buyer, cand) => {
    const A = tokens(buyer); const B = new Set(tokens(cand));
    if (!A.length || !B.size) return 0;
    let h = 0; for (const t of A) if (B.has(t)) h++; return h / A.length;
  };
  const rootLabel = (d) => String(d || '').replace(/^www\./, '').split('.')[0];
  const blocked = (host) => BLOCKLIST.some((b) => host.includes(b));
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  // ---- search services (return [{url,title}]) ---------------------------
  const braveSearch = async (q) => {
    const r = await fetch('https://api.search.brave.com/res/v1/web/search?count=5&q=' +
      encodeURIComponent(q), {
      headers: { 'X-Subscription-Token': braveKey, 'Accept': 'application/json' },
      signal: AbortSignal.timeout(10000),
    });
    const j = await r.json();
    return ((j.web && j.web.results) || []).map((x) => ({ url: x.url, title: x.title }));
  };
  const serperSearch = async (q) => {
    const r = await fetch('https://google.serper.dev/search', {
      method: 'POST',
      headers: { 'X-API-KEY': serperKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({ q, num: 5 }), signal: AbortSignal.timeout(10000),
    });
    const j = await r.json();
    return (j.organic || []).map((x) => ({ url: x.link, title: x.title }));
  };
  const tavilySearch = async (q) => {
    const r = await fetch('https://api.tavily.com/search', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ api_key: tavilyKey, query: q, max_results: 5, search_depth: 'basic' }),
      signal: AbortSignal.timeout(12000),
    });
    const j = await r.json();
    return (j.results || []).map((x) => ({ url: x.url, title: x.title }));
  };

  const services = [];
  if (braveKey) services.push({ name: 'brave', fn: braveSearch });
  if (serperKey) services.push({ name: 'serper', fn: serperSearch });
  if (tavilyKey) services.push({ name: 'tavily', fn: tavilySearch });

  // pick a valid company domain from a service's results
  const pickDomain = (items, buyerName) => {
    const bt = tokens(buyerName);
    for (const it of items) {
      let host = '';
      try { host = new URL(it.url).hostname.replace(/^www\./, '').toLowerCase(); }
      catch { continue; }
      if (!host || blocked(host)) continue;
      const label = rootLabel(host);
      const strongTok = bt.find((t) => t.length >= 5 && !COMMON.has(t) && label.includes(t));
      const cov = coverage(buyerName, it.title || '');
      if (strongTok || cov >= 0.999) {
        return { domain: host, matchedVia: strongTok ? 'domain-label' : 'title' };
      }
    }
    return null;
  };

  const hasMX = async (domain) => {
    try {
      const r = await fetch('https://dns.google/resolve?name=' + domain + '&type=MX',
        { signal: AbortSignal.timeout(8000) });
      const j = await r.json();
      return Array.isArray(j.Answer) && j.Answer.length > 0;
    } catch { return false; }
  };

  // ---- process -----------------------------------------------------------
  const out = [];
  let resolved = 0, stillReview = 0, capReached = 0;
  const svcCalls = {};
  let lookups = 0;

  for (const b of rows) {
    const retryable = b.enrichStatus === 'needs_review' || b.enrichStatus === 'no_domain_free';
    if (!retryable) { out.push(b); continue; }
    if ((b.icpScore || 0) < icpThreshold) { out.push(b); stillReview++; continue; }
    if (!services.length) { out.push(b); stillReview++; continue; }
    if (lookups >= maxLookups) { capReached++; out.push({ ...b, enrichStatus: 'needs_review_cap' }); continue; }

    lookups++;
    const country = (b.destinations && b.destinations[0]) || '';
    const query = `${b.buyerName} ${country} official website`.trim();

    let hit = null, via = '';
    for (const svc of services) {
      try {
        const items = await svc.fn(query);
        svcCalls[svc.name] = (svcCalls[svc.name] || 0) + 1;
        const picked = pickDomain(items, b.buyerName);
        await sleep(250);
        if (picked) { hit = picked.domain; via = svc.name + '_' + picked.matchedVia; break; }
      } catch { /* try next service */ }
    }

    if (!hit) { out.push({ ...b, enrichStatus: 'needs_review' }); stillReview++; continue; }

    const mx = await hasMX(hit); await sleep(150);
    const candidates = mx ? ROLE_PREFIXES.map((p) => `${p}@${hit}`) : [];
    if (candidates.length) resolved++;
    out.push({
      ...b, domain: hit, domainConfidence: 'high', domainSource: via, hasMX: mx,
      emailCandidates: candidates, primaryEmail: candidates[0] || '',
      enrichStatus: mx ? 'role_inbox_ready' : 'domain_no_mx',
    });
  }

  return {
    enriched: out,
    stats: { inputBuyers: rows.length, lookups, resolvedRoleInbox: resolved,
      stillNeedsReview: stillReview, skippedCapReached: capReached, serviceCalls: svcCalls },
  };
};

/**
 * Activepieces Code piece — Stack 2c: People / mail finder CASCADE.
 *
 * Once a buyer has a domain, find the real decision-maker(s) — name, title and
 * email — preferring procurement/purchasing roles. Tries services in order,
 * first that returns a usable person wins; up to 2 SPOCs kept. When found, the
 * buyer's primaryEmail is upgraded from the role inbox to the person's email,
 * and spocFirstName drives the greeting ("Hi Priya,").
 *
 *   1) Hunter.io   (Domain Search: name+title+department+email)  api_key
 *   2) Apollo.io   (People Search)                               X-Api-Key
 *   3) Snov.io     (OAuth token -> domain emails with info)      client id+secret
 *
 * Runs only on role_inbox_ready buyers that clear ICP and don't already have a
 * name (from the sheet), so credits aren't wasted.
 *
 * INPUTS:
 *   enriched        = Stack-2b `enriched` array
 *   hunterApiKey
 *   apolloApiKey
 *   snovClientId, snovClientSecret
 *   maxLookups      = cap per run (default 25)
 *   icpThreshold    = default 4
 *
 * OUTPUT { enriched, stats }
 */

export const code = async (inputs) => {
  const rows = Array.isArray(inputs.enriched) ? inputs.enriched : [];
  const hunterKey = inputs.hunterApiKey || '';
  const apolloKey = inputs.apolloApiKey || '';
  const snovId = inputs.snovClientId || '';
  const snovSecret = inputs.snovClientSecret || '';
  const maxLookups = Number(inputs.maxLookups) > 0 ? Number(inputs.maxLookups) : 25;
  const icpThreshold = Number(inputs.icpThreshold) >= 0 ? Number(inputs.icpThreshold) : 4;

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const cap = (s) => s ? s[0].toUpperCase() + s.slice(1).toLowerCase() : '';
  const clean = (s) => String(s || '').trim();

  // rank a title: procurement roles first, then owners/execs, then managers
  const titleScore = (title) => {
    const t = String(title || '').toLowerCase();
    if (/purchas|procure|sourc|supply|buyer|vendor/.test(t)) return 3;
    if (/owner|founder|proprietor|ceo|president|managing director|principal/.test(t)) return 2;
    if (/director|head|manager|vp|chief|purchase/.test(t)) return 1;
    return 0;
  };

  // normalize a service's people list -> [{name,first,title,email,confidence}]
  const rankPeople = (people) => {
    const seen = new Set();
    return people
      .filter((p) => p && p.email && String(p.email).includes('@'))
      .map((p) => {
        const first = cap(clean(p.first));
        const last = cap(clean(p.last));
        return {
          name: [first, last].filter(Boolean).join(' '),
          first, title: clean(p.title), email: clean(p.email).toLowerCase(),
          confidence: Number(p.confidence || 0), score: titleScore(p.title),
        };
      })
      .filter((p) => { if (seen.has(p.email)) return false; seen.add(p.email); return true; })
      .sort((a, b) => (b.score - a.score) || (b.confidence - a.confidence))
      .slice(0, 2);
  };

  // ---- services (each returns raw people [{first,last,title,email,confidence}]) ----
  const hunter = async (domain) => {
    const r = await fetch('https://api.hunter.io/v2/domain-search?limit=10&domain=' +
      encodeURIComponent(domain) + '&api_key=' + encodeURIComponent(hunterKey),
      { signal: AbortSignal.timeout(12000) });
    const j = await r.json();
    const emails = (j.data && j.data.emails) || [];
    return emails.map((e) => ({ first: e.first_name, last: e.last_name,
      title: e.position || e.department, email: e.value, confidence: e.confidence }));
  };

  const apollo = async (domain) => {
    const r = await fetch('https://api.apollo.io/v1/mixed_people/search', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Cache-Control': 'no-cache',
        'X-Api-Key': apolloKey },
      body: JSON.stringify({
        q_organization_domains: domain,
        person_titles: ['purchasing', 'procurement', 'sourcing', 'buyer',
          'supply chain', 'owner', 'founder', 'director'],
        page: 1, per_page: 10,
      }),
      signal: AbortSignal.timeout(12000),
    });
    const j = await r.json();
    return (j.people || []).map((p) => ({ first: p.first_name, last: p.last_name,
      title: p.title, email: p.email, confidence: 0 }));
  };

  let snovToken = null;
  const snov = async (domain) => {
    if (!snovToken) {
      const tr = await fetch('https://api.snov.io/v1/oauth/access_token', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ grant_type: 'client_credentials',
          client_id: snovId, client_secret: snovSecret }),
        signal: AbortSignal.timeout(12000),
      });
      const tj = await tr.json();
      snovToken = tj.access_token;
      if (!snovToken) throw new Error('snov auth failed');
    }
    const r = await fetch('https://api.snov.io/v2/domain-emails-with-info', {
      method: 'POST',
      headers: { 'Authorization': 'Bearer ' + snovToken, 'Content-Type': 'application/json' },
      body: JSON.stringify({ domain, type: 'personal', limit: 10, lastId: 0 }),
      signal: AbortSignal.timeout(12000),
    });
    const j = await r.json();
    return (j.emails || []).map((e) => ({ first: e.firstName, last: e.lastName,
      title: e.position, email: e.email, confidence: 0 }));
  };

  const services = [];
  if (hunterKey) services.push({ name: 'hunter', fn: hunter });
  if (apolloKey) services.push({ name: 'apollo', fn: apollo });
  if (snovId && snovSecret) services.push({ name: 'snov', fn: snov });

  // ---- process -----------------------------------------------------------
  const out = [];
  let found = 0, notFound = 0, capReached = 0, lookups = 0;
  const svcHits = {};

  for (const b of rows) {
    const eligible = b.enrichStatus === 'role_inbox_ready' && b.domain &&
      !b.spocFirstName && (b.icpScore || 0) >= icpThreshold;
    if (!eligible) { out.push(b); continue; }
    if (!services.length) { out.push(b); continue; }
    if (lookups >= maxLookups) { capReached++; out.push(b); continue; }

    lookups++;
    let spocs = [];
    let source = '';
    for (const svc of services) {
      try {
        const people = await svc.fn(b.domain);
        await sleep(300);
        const ranked = rankPeople(people || []);
        if (ranked.length) { spocs = ranked; source = svc.name; svcHits[svc.name] = (svcHits[svc.name] || 0) + 1; break; }
      } catch { /* next service */ }
    }

    if (!spocs.length) { notFound++; out.push(b); continue; }

    const primary = spocs[0];
    found++;
    out.push({
      ...b,
      spocName: primary.name,
      spocFirstName: primary.first,
      spocTitle: primary.title,
      spocEmail: primary.email,
      spocs,
      spocSource: source,
      // email the real person instead of the role inbox
      primaryEmail: primary.email || b.primaryEmail,
    });
  }

  return {
    enriched: out,
    stats: { inputBuyers: rows.length, lookups, spocFound: found,
      spocNotFound: notFound, skippedCapReached: capReached, serviceHits: svcHits },
  };
};

/**
 * Activepieces Code piece — CRM report (ingest + domain gate + found log).
 *
 * Flow position:  enrichment (02 / 02b / 02c)  ->  THIS  ->  03-personalize.
 *
 * Three jobs, once enrichment has resolved domains:
 *
 *  1. **Reliable domain gate.** crm-precheck deduped cheaply on name; now that
 *     we have a domain, a second `GET /lookup?domain=` catches the same company
 *     under a different name ("Ecoware India" vs "Ecoware NZ") and drops it if
 *     it is already in the pipeline. Cache hits skip this — they were already
 *     confirmed known.
 *  2. **Report to the CRM** (`POST /ingest`): one batch of `company` and
 *     `contact` records. Identity only; the CRM owns the CRM. NEVER a send event —
 *     the CRM reads sends from the mailbox and rejects reported sends with 422.
 *     Idempotent, so a retried step is a no-op.
 *  3. **Emit outputs:** `toPersonalize` (prospects ready to pitch) and
 *     `foundLog` (one row per company we resolved a domain for, to append to
 *     the Found sheet so next run's crm-precheck reuses it).
 *
 * `needs_address` buyers are reported (so the CRM learns the address) but NOT
 * put in `toPersonalize` — the CRM queues them for follow-up, we don't cold-pitch.
 *
 * INPUTS
 *   buyers      = the enriched array (02c.enriched, or 02b/02.enriched)
 *   crmBaseUrl  = default https://your-crm.example.com
 *   crmToken    = CRM_API_TOKEN (bearer). Blank -> report is skipped, pipeline
 *                 still runs (nothing lands in the CRM).
 *   batch       = optional batch id (defaults to a timestamp)
 *
 * OUTPUT { toPersonalize, foundLog, ingest, records, stats }
 */

export const code = async (inputs) => {
  const buyers = Array.isArray(inputs.buyers) ? inputs.buyers : [];
  const base = String(inputs.crmBaseUrl || 'https://your-crm.example.com')
    .replace(/\/+$/, '');
  const token = String(inputs.crmToken || '').trim();
  const batch = String(inputs.batch || ('A-' + new Date().toISOString().slice(0, 19)));

  const clean = (s) => (s === null || s === undefined ? '' : String(s)).replace(/\s+/g, ' ').trim();
  const normDomain = (v) => {
    const h = clean(v).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0];
    return h.includes('.') && !h.includes('@') && !h.includes(' ') ? h : '';
  };
  const nowIso = new Date().toISOString();
  const sleep = (ms) => new Promise((res) => setTimeout(res, ms));

  const lookup = async (domain) => {
    if (!token || !domain) return null;
    try {
      const r = await fetch(base + '/lookup?domain=' + encodeURIComponent(domain), {
        headers: { Authorization: 'Bearer ' + token },
        signal: AbortSignal.timeout(15000),
      });
      if (!r.ok) return null;
      return await r.json();
    } catch { return null; }
  };

  const toPersonalize = [];
  const foundLog = [];
  const records = [];
  const seenCompany = new Set();
  const stats = { input: buyers.length, prospects: 0, needsAddress: 0,
    domainDupSkipped: 0, companies: 0, contacts: 0 };

  for (const b of buyers) {
    const domain = normDomain(b.domain);

    // log every company we resolved a domain for (drives next run's cache)
    if (domain) {
      foundLog.push({
        buyerKey: b.buyerKey || '', buyerName: b.buyerName || '',
        domain, domainConfidence: b.domainConfidence || '',
        spocName: b.spocName || '', spocEmail: b.spocEmail || '',
        mailFound: b.primaryEmail || '', enrichStatus: b.enrichStatus || '',
        foundAt: nowIso,
      });
    }
    if (!domain) continue;

    // reliable domain gate — only for freshly enriched buyers (cache hits and
    // needs_address were already resolved by crm-precheck)
    if (b.dedupe !== 'cache' && b.dedupe !== 'crm_needs_address') {
      const info = await lookup(domain);
      await sleep(120);
      if (info && info.known && info.should_prospect === false && !info.needs_address) {
        stats.domainDupSkipped++;
        continue; // same company under another name — already in the pipeline
      }
    }

    // report the company (one per domain, idempotent)
    if (!seenCompany.has(domain)) {
      seenCompany.add(domain);
      records.push({ op: 'company', name: b.buyerName || domain, domain,
        website: 'https://' + domain,
        country: (b.destinations && b.destinations[0]) || b.country || '' });
      stats.companies++;
    }
    // report the contact if we have a real address
    const email = clean(b.primaryEmail);
    if (email.includes('@')) {
      records.push({ op: 'contact', company: domain, email,
        full_name: b.spocName || '', title: b.spocTitle || '',
        linkedin_url: b.linkedinUrl || '' });
      stats.contacts++;
    }

    if (b.needsAddress) { stats.needsAddress++; continue; } // don't cold-pitch
    if (b.enrichStatus === 'role_inbox_ready' && email.includes('@')) {
      toPersonalize.push(b);
      stats.prospects++;
    }
  }

  // ---- one ingest call for the whole batch (all-or-nothing) --------------
  let ingest = { skipped: 'no crmToken' };
  if (token && records.length) {
    try {
      const r = await fetch(base + '/ingest', {
        method: 'POST',
        headers: { Authorization: 'Bearer ' + token, 'Content-Type': 'application/json' },
        body: JSON.stringify({ service: 'A', batch, records }),
        signal: AbortSignal.timeout(60000),
      });
      const body = await r.json().catch(() => ({}));
      ingest = { status: r.status, ...body };
    } catch (e) {
      ingest = { error: String(e && e.message) };
    }
  } else if (token) {
    ingest = { skipped: 'nothing to report' };
  }

  return { toPersonalize, foundLog, ingest, records: records.length, stats };
};

/**
 * Activepieces Code piece — Stack 3 (BATCH): personalize many buyers in one step.
 *
 * Same logic as 03-personalize.js but takes the whole enriched array, splits it
 * into ready-to-send vs needs-review, and personalizes each ready buyer via Groq
 * with a small delay (respects free-tier rate limits). Avoids Activepieces Loop
 * result-aggregation entirely.
 *
 * INPUTS:
 *   enriched     = Stack-2b `enriched` array
 *   llmApiKey    = your OpenRouter API key (openrouter.ai/keys)   [required]
 *   model        = default 'inclusionai/ling-3.0-flash'
 *   llmBaseUrl   = default OpenRouter chat/completions endpoint
 *   jsonMode     = default false (Ling rejects response_format; the tolerant
 *                  parser below handles ```json-fenced output). Set true only
 *                  for a provider you've confirmed supports json_object.
 *   senderName   = default 'the sender'
 *   catalogUrl   = optional
 *   maxToWrite   = optional cap on LLM calls per run (default 25)
 *   delayMs      = optional gap between LLM calls (default 1200)
 *   appUrl       = optional, sent as OpenRouter HTTP-Referer (app ranking)
 *   appName      = optional, sent as OpenRouter X-Title (app ranking)
 *
 * OUTPUT { emails, review, stats }
 *   emails = [{ to, subject, body, buyerKey, buyerName, track }]  -> feed to 04a
 *   review = [ buyers with needs_review* ]                        -> Review tab
 */

export const code = async (inputs) => {
  const rows = Array.isArray(inputs.enriched) ? inputs.enriched : [];
  // Provider-agnostic LLM over an OpenAI-compatible endpoint. Defaults to
  // inclusionAI Ling via OpenRouter. To swap providers, change llmBaseUrl +
  // model + llmApiKey. (Older key names still accepted for back-compat.)
  const apiKey = inputs.llmApiKey || inputs.openRouterApiKey ||
    inputs.openrouterApiKey || inputs.geminiApiKey || inputs.groqApiKey;
  const model = inputs.model || 'inclusionai/ling-3.0-flash';
  const baseUrl = inputs.llmBaseUrl ||
    'https://openrouter.ai/api/v1/chat/completions';
  // Ling rejects response_format; default OFF and lean on parseJson(). Only
  // enable for a provider you've confirmed supports json_object.
  const jsonMode = inputs.jsonMode === true;
  const senderName = inputs.senderName || 'the sender';
  const catalogUrl = inputs.catalogUrl || '';
  const maxToWrite = Number(inputs.maxToWrite) > 0 ? Number(inputs.maxToWrite) : 25;
  const delayMs = Number(inputs.delayMs) >= 0 ? Number(inputs.delayMs) : 1200;

  const Acme = {
    company: 'Acme Exports',
    product: 'compostable sugarcane bagasse tableware (HS 4823.70)',
    range: '100+ SKUs — plates, bowls, clamshells, cups, containers, egg cartons',
    capacity: '15 tons/day',
    proof: 'certified, international quality standards; maintained product weight/thickness for high durability and oil & grease resistance (OGR)',
    valueUS: 'lower overall landed cost so you can compete in the US market, faster turnarounds and quicker shipments, and a reliable India-based alternative as China tariffs raise import costs',
    valueROW: 'competitive Ex-factory and FOB pricing from India, diversified sourcing, and a consistent supply chain to optimise landed cost and inventory',
  };

  const norm = (s) => String(s || '').toLowerCase();
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  // tolerant JSON parse — some models wrap output in ```json ... ``` fences
  const parseJson = (s) => {
    let t = String(s || '').trim();
    const m = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
    if (m) t = m[1].trim();
    return JSON.parse(t);
  };

  // Greeting target: a real person's first name if we have one, else the role
  // behind the inbox we're mailing (purchasing@ -> "Procurement Team"). Never
  // the company name.
  const roleGreeting = (email) => {
    const local = String(email || '').toLowerCase().split('@')[0];
    if (/purchas|procure|sourc|buyer/.test(local)) return 'Procurement Team';
    if (/import|order/.test(local)) return 'Purchasing Team';
    return 'Team';
  };

  const writeOne = async (b) => {
    const dest = norm((b.destinations && b.destinations[0]) || b.country || '');
    const isUS = /united states|usa|u\.s|america/.test(dest);
    const track = isUS ? 'US' : 'ROW';
    // only greet a person by name if we're actually emailing that person
    const emailingPerson = b.spocEmail && b.primaryEmail &&
      String(b.spocEmail).toLowerCase() === String(b.primaryEmail).toLowerCase();
    const greetName = (emailingPerson && b.spocFirstName)
      ? b.spocFirstName : roleGreeting(b.primaryEmail);
    const sourceText = norm([].concat(b.origins || [], b.sellers || []).join(' '));
    const chinaHook = /china|chinese|zhejiang|guangzhou|shenzhen|ningbo|shanghai|fujian|xiamen|zhongxin/.test(sourceText);
    const importedProduct = (b.productLabels && b.productLabels[0]) ||
      (b.products && b.products[0]) || 'bagasse / molded-fiber tableware';

    const system =
      `You are ${senderName}, founder of ${Acme.company}. You write short, ` +
      `direct B2B cold outreach emails to importers of disposable foodservice ` +
      `tableware. Plain, human, no fluff. 90-140 words. Never invent facts about ` +
      `the recipient beyond what is given. The email MUST open with exactly ` +
      `"Hi ${greetName}," and must NOT address the recipient by their company ` +
      `name in the greeting. Return ONLY valid JSON: ` +
      `{"subject":"...","body":"..."}. No signature block. One clear CTA.`;
    const track_brief = isUS
      ? `Track: US importer. Lead with the China-tariff angle ONLY if chinaHook=${chinaHook}. Value: ${Acme.valueUS}.`
      : `Track: non-US importer. Angle: diversify sourcing from India. Value: ${Acme.valueROW}.`;
    const user =
      `Write a personalized cold email.\nRecipient company: ${b.buyerName}\n` +
      `They import: ${importedProduct}\nCurrently sourcing from China: ${chinaHook}\n` +
      `${track_brief}\nAbout us: ${Acme.company} supplies ${Acme.product}. ` +
      `Range: ${Acme.range}. Capacity: ${Acme.capacity}. Proof: ${Acme.proof}.\n` +
      (catalogUrl ? `Mention a product catalogue is attached.\n` : '') +
      `CTA: ask for a quick call to discuss SKUs, samples and landed pricing (US) ` +
      `or which SKUs interest them for an Ex-factory/FOB quote (non-US).`;

    const payload = {
      model, temperature: 0.6,
      messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
    };
    if (jsonMode) payload.response_format = { type: 'json_object' };
    const headers = { 'Authorization': 'Bearer ' + apiKey, 'Content-Type': 'application/json' };
    // OpenRouter optional attribution headers — safe to omit for other providers.
    if (inputs.appUrl) headers['HTTP-Referer'] = String(inputs.appUrl);
    if (inputs.appName) headers['X-Title'] = String(inputs.appName);
    const r = await fetch(baseUrl, {
      method: 'POST',
      headers,
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(20000),
    });
    if (!r.ok) {
      const t = await r.text().catch(() => '');
      throw new Error('HTTP ' + r.status + ': ' + t.slice(0, 300));
    }
    const j = await r.json();
    const content = j.choices && j.choices[0] && j.choices[0].message &&
      j.choices[0].message.content;
    if (!content) throw new Error('no content in response: ' + JSON.stringify(j).slice(0, 300));
    const p = parseJson(content);
    const signature = `\n\n${senderName}\nFounder, ${Acme.company}` +
      (catalogUrl ? `\nProduct catalogue: ${catalogUrl}` : '');
    return {
      to: b.primaryEmail || '',
      subject: String(p.subject || '').trim(),
      body: (String(p.body || '').trim() + signature),
      buyerKey: b.buyerKey, buyerName: b.buyerName, track,
      domain: b.domain || '',
      spoc: b.spocName ? (b.spocName + (b.spocTitle ? ', ' + b.spocTitle : '')) : 'Role inbox',
    };
  };

  // Anything plausibly a target but unresolved goes to the Review tab so nothing
  // is silently lost when the 02b fallback step is skipped. (skipped_low_icp =
  // intentional off-target drop, not reviewed.)
  const REVIEW_STATUSES = new Set([
    'needs_review', 'needs_review_cap', 'no_domain_free', 'domain_no_mx',
  ]);
  const ready = rows.filter((b) => b.enrichStatus === 'role_inbox_ready' && b.primaryEmail);
  const review = rows.filter((b) => REVIEW_STATUSES.has(b.enrichStatus));

  const emails = [];
  const errors = [];
  const stats = { readyIn: ready.length, written: 0, failed: 0, reviewOut: review.length };

  for (const b of ready.slice(0, maxToWrite)) {
    try {
      const e = await writeOne(b);
      if (e.subject && e.body) { emails.push(e); stats.written++; }
      else { stats.failed++; if (errors.length < 3) errors.push('empty subject/body'); }
    } catch (err) {
      stats.failed++;
      if (errors.length < 3) errors.push(String(err && err.message));
    }
    if (delayMs) await sleep(delayMs);
  }
  stats.errors = errors;

  return { emails, review, stats };
};

/**
 * Activepieces Code piece — Stack 5: Queue gate (dedup -> Outbox for approval).
 *
 * Takes the personalized emails and produces rows to APPEND to the Outbox tab
 * for human approval. Skips any buyer already handled — present in the Sent log
 * (already emailed) OR already in the Outbox (already queued/pending) — so a
 * re-dumped sheet with old rows never re-queues or re-sends anyone.
 *
 * Flow: personalize -> get_sent + get_outbox -> THIS -> Loop -> Insert Row (Outbox).
 *
 * INPUTS:
 *   emails   = personalize `emails` array
 *   sentLog  = rows from the Sent tab
 *   outbox   = rows from the Outbox tab
 *
 * OUTPUT { toQueue, stats }
 *   toQueue = rows to append to Outbox (approved left blank for you to fill)
 */

export const code = async (inputs) => {
  const normSheet = (v) => {
    let rows = Array.isArray(v) ? v
      : (v && (Array.isArray(v.rows) ? v.rows
        : Array.isArray(v.values) ? v.values
        : Array.isArray(v.body) ? v.body : [])) || [];
    if (!Array.isArray(rows)) rows = [];
    rows = rows.map((r) => (r && typeof r.values === 'object' && r.values) ? { row: r.row, ...r.values } : r);
    const lettered = rows.some((r) => r && (r.A !== undefined || r.B !== undefined));
    if (!lettered) return rows;
    const header = rows.find((r) => String(r.row) === '1') || rows[0];
    if (!header) return [];
    const map = {};
    for (const [k, val] of Object.entries(header)) if (k !== 'row') map[k] = String(val).trim();
    const out = [];
    for (const r of rows) {
      if (r === header || String(r.row) === '1') continue;
      const obj = {};
      if (r.row !== undefined) obj.row = r.row;
      for (const [k, val] of Object.entries(r)) {
        if (k === 'row') continue;
        const name = map[k];
        if (name) obj[name] = val;
      }
      out.push(obj);
    }
    return out;
  };

  const emails = Array.isArray(inputs.emails) ? inputs.emails : [];
  const sentLog = normSheet(inputs.sentLog);
  const outbox = normSheet(inputs.outbox);

  const lc = (s) => String(s || '').toLowerCase().trim();

  // anyone already emailed OR already queued is "handled"
  const handledKeys = new Set();
  const handledEmails = new Set();
  for (const r of [...sentLog, ...outbox]) {
    if (r.buyerKey) handledKeys.add(lc(r.buyerKey));
    if (r.to) handledEmails.add(lc(r.to));
  }

  const toQueue = [];
  const seen = new Set();
  const skipped = { alreadyHandled: 0, noAddress: 0, dupInBatch: 0 };
  const nowIso = new Date().toISOString();

  for (const e of emails) {
    const to = lc(e.to);
    if (!to || !to.includes('@')) { skipped.noAddress++; continue; }
    if (handledKeys.has(lc(e.buyerKey)) || handledEmails.has(to)) { skipped.alreadyHandled++; continue; }
    if (seen.has(to)) { skipped.dupInBatch++; continue; }
    seen.add(to);

    toQueue.push({
      buyerKey: e.buyerKey || '',
      buyerName: e.buyerName || '',
      domain: e.domain || '',
      spoc: e.spoc || '',
      to: e.to,
      subject: e.subject || '',
      body: e.body || '',
      track: e.track || '',
      approved: '',            // <-- you set this to "yes" to release the email
      status: 'pending',
      queuedAt: nowIso,
    });
  }

  return {
    toQueue,
    stats: { emailsIn: emails.length, queued: toQueue.length, ...skipped },
  };
};

/**
 * Activepieces Code piece — Stack 6: Approved-send gate.
 *
 * Reads the Outbox tab and releases ONLY rows you approved and that haven't been
 * sent yet. Applies the same throttle + test-mode redirect as the old send gate.
 * Produces: the batch to send, the Sent-log rows to append, and the Outbox rows
 * to mark as sent.
 *
 * Flow: get_outbox -> THIS -> Loop(toSend)->Gmail -> Loop(newLogRows)->Insert Sent
 *       -> Loop(outboxUpdates)->Update Row (Outbox).
 *
 * INPUTS:
 *   outbox        = rows from the Outbox tab (must include each row's line number)
 *   sentLog       = rows from the Sent tab (for the daily counter + safety dedup)
 *   maxPerRun     = default 5
 *   dailyCap      = default 40
 *   testMode      = boolean
 *   testRecipient = your inbox (required if testMode)
 *
 * OUTPUT { toSend, newLogRows, outboxUpdates, skipped }
 */

export const code = async (inputs) => {
  const normSheet = (v) => {
    let rows = Array.isArray(v) ? v
      : (v && (Array.isArray(v.rows) ? v.rows
        : Array.isArray(v.values) ? v.values
        : Array.isArray(v.body) ? v.body : [])) || [];
    if (!Array.isArray(rows)) rows = [];
    rows = rows.map((r) => (r && typeof r.values === 'object' && r.values) ? { row: r.row, ...r.values } : r);
    const lettered = rows.some((r) => r && (r.A !== undefined || r.B !== undefined));
    if (!lettered) return rows;
    const header = rows.find((r) => String(r.row) === '1') || rows[0];
    if (!header) return [];
    const map = {};
    for (const [k, val] of Object.entries(header)) if (k !== 'row') map[k] = String(val).trim();
    const out = [];
    for (const r of rows) {
      if (r === header || String(r.row) === '1') continue;
      const obj = {};
      if (r.row !== undefined) obj.row = r.row;
      for (const [k, val] of Object.entries(r)) {
        if (k === 'row') continue;
        const name = map[k];
        if (name) obj[name] = val;
      }
      out.push(obj);
    }
    return out;
  };

  const outbox = normSheet(inputs.outbox);
  const sentLog = normSheet(inputs.sentLog);
  const maxPerRun = Number(inputs.maxPerRun) > 0 ? Number(inputs.maxPerRun) : 5;
  const dailyCap = Number(inputs.dailyCap) > 0 ? Number(inputs.dailyCap) : 40;
  const testMode = Boolean(inputs.testMode);
  const testRecipient = String(inputs.testRecipient || '').trim();

  const lc = (s) => String(s || '').toLowerCase().trim();
  const today = new Date().toISOString().slice(0, 10);
  const isApproved = (v) => /^(y|yes|true|1|approve|approved|✓|x)$/i.test(String(v || '').trim());
  const isSent = (v) => /^(sent|done)$/i.test(String(v || '').trim());

  if (testMode && !testRecipient) {
    return { toSend: [], newLogRows: [], outboxUpdates: [],
      skipped: { error: 'testMode on but no testRecipient' } };
  }

  // already-sent guard + today's counter (from Sent log)
  const sentKeys = new Set();
  let sentToday = 0;
  for (const r of sentLog) {
    if (r.buyerKey) sentKeys.add(lc(r.buyerKey));
    if (String(r.sentAt || '').slice(0, 10) === today) sentToday++;
  }

  const skipped = { notApproved: 0, alreadySent: 0, noRow: 0 };
  const eligible = [];
  for (const r of outbox) {
    if (!isApproved(r.approved)) { skipped.notApproved++; continue; }
    if (isSent(r.status) || sentKeys.has(lc(r.buyerKey))) { skipped.alreadySent++; continue; }
    if (r.row === undefined || r.row === null || r.row === '') { skipped.noRow++; continue; }
    eligible.push(r);
  }

  const remainingDaily = Math.max(0, dailyCap - sentToday);
  const takeN = Math.min(maxPerRun, remainingDaily, eligible.length);
  const batch = eligible.slice(0, takeN);

  const nowIso = new Date().toISOString();
  const toSend = [];
  const newLogRows = [];
  const outboxUpdates = [];

  for (const r of batch) {
    const realTo = r.to;
    toSend.push({
      to: testMode ? testRecipient : realTo,
      subject: testMode ? `[TEST → ${realTo}] ${r.subject}` : r.subject,
      body: r.body,
    });
    newLogRows.push({
      buyerKey: r.buyerKey || '', buyerName: r.buyerName || '', to: realTo,
      subject: r.subject || '', track: r.track || '', status: 'sent',
      sentAt: nowIso, lastActionAt: nowIso, followupCount: 0,
      testMode: testMode ? 'yes' : 'no',
    });
    outboxUpdates.push({ row: r.row, status: 'sent', sentAt: nowIso });
  }

  return {
    toSend, newLogRows, outboxUpdates,
    skipped: { ...skipped, sentTodayBefore: sentToday,
      eligible: eligible.length, sending: batch.length,
      heldByThrottle: Math.max(0, eligible.length - batch.length) },
  };
};
